function hcd_json(bool $success,string $message='',array $data=[],int $code=200):void{http_response_code($code);echo json_encode(array_merge(['success'=>$success,'message'=>$message],$data),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function hcd_tables(PDO $pdo):void{$pdo->exec("CREATE TABLE IF NOT EXISTS hotspot_traffic_user_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,router_id INT NULL,username VARCHAR(100) NOT NULL,session_id VARCHAR(120) NOT NULL DEFAULT '',recorded_at DATETIME NOT NULL,bytes_in BIGINT UNSIGNED NOT NULL DEFAULT 0,bytes_out BIGINT UNSIGNED NOT NULL DEFAULT 0,upload_bps DECIMAL(20,2) NOT NULL DEFAULT 0,download_bps DECIMAL(20,2) NOT NULL DEFAULT 0,address VARCHAR(64) NOT NULL DEFAULT '',interface_name VARCHAR(150) NOT NULL DEFAULT '',KEY idx_huh_router_user_time(router_id,username,recorded_at),KEY idx_huh_user_session_time(username,session_id,recorded_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");}
function hcd_range(string $r):int{return ['1h'=>1,'6h'=>6,'24h'=>24,'7d'=>168,'30d'=>720][$r]??24;}
function hcd_usage(PDO $pdo,int $routerId,string $user,int $hours):array{$q=$pdo->prepare("SELECT session_id,bytes_in,bytes_out FROM hotspot_traffic_user_history WHERE router_id=? AND username=? AND recorded_at>=DATE_SUB(NOW(),INTERVAL {$hours} HOUR) ORDER BY recorded_at ASC,id ASC");$q->execute([$routerId,$user]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$down=0;$up=0;$prev=[];foreach($rows as $r){$sid=(string)$r['session_id'];if($sid!==''&&isset($prev[$sid])){$di=(int)$r['bytes_in']-$prev[$sid][0];$do=(int)$r['bytes_out']-$prev[$sid][1];if($di>=0)$up+=$di;if($do>=0)$down+=$do;}$prev[$sid]=[(int)$r['bytes_in'],(int)$r['bytes_out']];}return ['download_bytes'=>(string)$down,'upload_bytes'=>(string)$up,'total_bytes'=>(string)($down+$up),'records'=>count($rows)];}
function hcd_daily(PDO $pdo,int $routerId,string $user,int $days):array{$q=$pdo->prepare("SELECT session_id,recorded_at,bytes_in,bytes_out FROM hotspot_traffic_user_history WHERE router_id=? AND username=? AND recorded_at>=DATE_SUB(CURDATE(),INTERVAL {$days} DAY) ORDER BY recorded_at ASC,id ASC");$q->execute([$routerId,$user]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$daily=[];$prev=[];foreach($rows as $r){$sid=(string)$r['session_id'];$day=substr((string)$r['recorded_at'],0,10);if(!isset($daily[$day]))$daily[$day]=['date'=>$day,'download_bytes'=>0,'upload_bytes'=>0,'total_bytes'=>0,'records'=>0];$daily[$day]['records']++;if($sid!==''&&isset($prev[$sid])){$di=(int)$r['bytes_in']-$prev[$sid][0];$do=(int)$r['bytes_out']-$prev[$sid][1];if($di>=0)$daily[$day]['upload_bytes']+=$di;if($do>=0)$daily[$day]['download_bytes']+=$do;}$prev[$sid]=[(int)$r['bytes_in'],(int)$r['bytes_out']];}foreach($daily as &$d){$d['total_bytes']=(string)($d['download_bytes']+$d['upload_bytes']);$d['download_bytes']=(string)$d['download_bytes'];$d['upload_bytes']=(string)$d['upload_bytes'];}unset($d);$start=(new DateTimeImmutable('today',new DateTimeZone('Asia/Jakarta')))->modify('-'.($days-1).' days');$out=[];for($i=0;$i<$days;$i++){ $day=$start->modify('+'.$i.' days')->format('Y-m-d');$out[]=$daily[$day]??['date'=>$day,'download_bytes'=>'0','upload_bytes'=>'0','total_bytes'=>'0','records'=>0];}return $out;}
function hcd_sessions(PDO $pdo,int $routerId,string $user,int $hours):array{$q=$pdo->prepare("SELECT session_id,recorded_at,bytes_in,bytes_out,address,interface_name,upload_bps,download_bps FROM hotspot_traffic_user_history WHERE router_id=? AND username=? AND recorded_at>=DATE_SUB(NOW(),INTERVAL {$hours} HOUR) ORDER BY recorded_at ASC,id ASC");$q->execute([$routerId,$user]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$sessions=[];foreach($rows as $r){$sid=(string)$r['session_id'];if($sid==='')$sid='legacy-'.substr(hash('sha256',(string)$r['address'].'|'.(string)$r['interface_name']),0,12);if(!isset($sessions[$sid]))$sessions[$sid]=['session_id'=>$sid,'start'=>(string)$r['recorded_at'],'end'=>(string)$r['recorded_at'],'bytes_in_start'=>(int)$r['bytes_in'],'bytes_out_start'=>(int)$r['bytes_out'],'bytes_in'=>(int)$r['bytes_in'],'bytes_out'=>(int)$r['bytes_out'],'address'=>(string)$r['address'],'interface'=>(string)$r['interface_name'],'peak_download_bps'=>(float)$r['download_bps'],'peak_upload_bps'=>(float)$r['upload_bps'],'records'=>0];$s=&$sessions[$sid];$s['end']=(string)$r['recorded_at'];$s['bytes_in']=(int)$r['bytes_in'];$s['bytes_out']=(int)$r['bytes_out'];$s['peak_download_bps']=max($s['peak_download_bps'],(float)$r['download_bps']);$s['peak_upload_bps']=max($s['peak_upload_bps'],(float)$r['upload_bps']);$s['records']++;unset($s);}foreach($sessions as &$s){$start=strtotime($s['start']);$end=strtotime($s['end']);$s['duration_seconds']=max(0,$end-$start);$s['duration']=$s['duration_seconds']<60?$s['duration_seconds'].' detik':($s['duration_seconds']<3600?floor($s['duration_seconds']/60).' menit':floor($s['duration_seconds']/3600).'j '.floor(($s['duration_seconds']%3600)/60).'m');$s['download_bytes']=(string)max(0,$s['bytes_out']-$s['bytes_out_start']);$s['upload_bytes']=(string)max(0,$s['bytes_in']-$s['bytes_in_start']);$s['total_bytes']=(string)((int)$s['download_bytes']+(int)$s['upload_bytes']);unset($s['bytes_in_start'],$s['bytes_out_start'],$s['bytes_in'],$s['bytes_out']);}unset($s);$sessions=array_values($sessions);usort($sessions,fn($a,$b)=>strcmp($b['start'],$a['start']));return $sessions;}
try{$username=trim((string)($_GET['username']??''));if($username==='')hcd_json(false,'Username Hotspot wajib diisi.',[],400);$range=(string)($_GET['range']??'24h');$hours=hcd_range($range);$config=new MikroTikConfig();$routerId=isset($_GET['router_id'])?(int)$_GET['router_id']:0;$router=$routerId>0?$config->getRouterById($routerId):$config->getRouter();if(!$router)hcd_json(false,'Router tidak ditemukan.',[],404);$routerId=(int)$router['id'];$pdo=(new Database())->connect();hcd_tables($pdo);$api=new RouterosAPI();$api->debug=false;$online=false;$active=null;$secret=null;if($api->connect($router['ip_address'],$router['username'],$router['password'],$router['api_port'])){$raw=(array)$api->comm('/ip/hotspot/active/print');foreach($raw as $row){if(is_array($row)&&strcasecmp(trim((string)($row['user']??'')),$username)===0){$active=$row;break;}}$users=(array)$api->comm('/ip/hotspot/user/print');foreach($users as $row){if(is_array($row)&&strcasecmp(trim((string)($row['name']??'')),$username)===0){$secret=$row;break;}}$online=$active!==null;$api->disconnect();}$st=$pdo->prepare("SELECT * FROM hotspot_traffic_user_history WHERE router_id=? AND username=? AND recorded_at>=DATE_SUB(NOW(),INTERVAL {$hours} HOUR) ORDER BY recorded_at ASC,id ASC");$st->execute([$routerId,$username]);$rows=$st->fetchAll(PDO::FETCH_ASSOC);$labels=[];$download=[];$upload=[];$details=[];$totalDown=0;$totalUp=0;$prev=[];$sumD=0.0;$sumU=0.0;$peakD=0.0;$peakU=0.0;$sessionsSeen=[];foreach($rows as $r){$sid=(string)$r['session_id'];$t=strtotime((string)$r['recorded_at']);$d=(float)$r['download_bps'];$u=(float)$r['upload_bps'];$sumD+=$d;$sumU+=$u;$peakD=max($peakD,$d);$peakU=max($peakU,$u);if($sid!==''&&isset($prev[$sid])){$di=(int)$r['bytes_in']-$prev[$sid]['in'];$do=(int)$r['bytes_out']-$prev[$sid]['out'];if($di>=0)$totalUp+=$di;if($do>=0)$totalDown+=$do;}$prev[$sid]=['in'=>(int)$r['bytes_in'],'out'=>(int)$r['bytes_out']];$labels[]=date('H:i:s',$t);$download[]=$d;$upload[]=$u;$details[]=['time'=>(string)$r['recorded_at'],'rx'=>(string)$r['bytes_in'],'tx'=>(string)$r['bytes_out'],'download_bps'=>$d,'upload_bps'=>$u,'address'=>(string)$r['address'],'interface'=>(string)$r['interface_name'],'session_id'=>$sid];if($sid!=='')$sessionsSeen[$sid]=true;}$count=count($rows);$latest=$count?$rows[$count-1]:null;$profile=(string)($active['profile']??($secret['profile']??''));$address=(string)($active['address']??($latest['address']??''));$mac=(string)($active['mac-address']??'');$interface=(string)($active['interface']??($latest['interface_name']??''));$uptime=(string)($active['uptime']??'');$loginBy=(string)($active['login-by']??'');$usage7=hcd_usage($pdo,$routerId,$username,168);$usage30=hcd_usage($pdo,$routerId,$username,720);$daily7=hcd_daily($pdo,$routerId,$username,7);$daily30=hcd_daily($pdo,$routerId,$username,30);$sessionRows=hcd_sessions($pdo,$routerId,$username,720);$totalSessionTraffic=0;$totalSessionSeconds=0;$longest=0;foreach($sessionRows as $s){$totalSessionTraffic+=(int)$s['total_bytes'];$totalSessionSeconds=max($totalSessionSeconds,(int)$s['duration_seconds']);}$sessionSummary=['count'=>count($sessionRows),'traffic_bytes'=>(string)$totalSessionTraffic,'longest_seconds'=>$totalSessionSeconds];hcd_json(true,'',['router_id'=>$routerId,'router_name'=>(string)$router['name'],'online'=>$online,'user'=>['username'=>$username,'profile'=>$profile,'address'=>$address,'mac_address'=>$mac,'interface'=>$interface,'uptime'=>$uptime,'login_by'=>$loginBy,'comment'=>(string)($secret['comment']??''),'limit_uptime'=>(string)($secret['limit-uptime']??''),'limit_bytes_in'=>(string)($secret['limit-bytes-in']??''),'limit_bytes_out'=>(string)($secret['limit-bytes-out']??'')],'latest_rx'=>(string)($latest['bytes_in']??0),'latest_tx'=>(string)($latest['bytes_out']??0),'average_download_bps'=>$count?$sumD/$count:0,'average_upload_bps'=>$count?$sumU/$count:0,'peak_download_bps'=>$peakD,'peak_upload_bps'=>$peakU,'total_download_bytes'=>(string)$totalDown,'total_upload_bytes'=>(string)$totalUp,'records'=>$count,'sessions'=>count($sessionsSeen),'usage_7d'=>$usage7,'usage_30d'=>$usage30,'daily_7d'=>$daily7,'daily_30d'=>$daily30,'session_summary'=>$sessionSummary,'sessions_detail'=>$sessionRows,'labels'=>$labels,'download_speed'=>$download,'upload_speed'=>$upload,'details'=>array_reverse(array_slice($details,-150))]);}catch(Throwable $e){hcd_json(false,$e->getMessage(),[],500);}
